/* keymap: what each key of the layout does, face, gold and blue (unit 018). One table for the
 * firmware and anything that draws the layout: generated by scripts/gen_keymap.py from the layout
 * (layout/stu32-v0.json, a copy of abacus's layout/stu32-v0.json) and checked against it
 * (--check), so the legends and the actions cannot drift apart. Keys are numbered as keys.h does:
 * row * 6 + column, the layout's rows and their keys in order.
 *
 * An action is one of: a core op (with its argument), an op that first asks for its argument (a
 * variable, a label or a target, typed on the keys that follow), a menu (its contents are the
 * soft keys'; not defined yet: the layout is not ruled), a shift, a soft key, or something the
 * device does itself (OFF, UNDO). A legend the generator has no meaning for is KM_UNDEFINED, and
 * the test lists them.
 *
 * Reading the table, the same on the device and in the app (ruled by abacus with tally, #3827):
 * - KM_NONE in a shift column means the key has no separate legend there: its face action applies.
 * - A soft key does its action in any shift, and the shift clears.
 * - A shift key pressed while that shift is armed cancels it (UG p.1-2); the other shift switches
 *   to it (abacus #3824). */
#ifndef KEYMAP_H
#define KEYMAP_H

#include "keys.h"

typedef enum {
    KM_NONE = 0,            /* no key, or no legend in this shift */
    KM_OP,                  /* ab_do_arg(op, arg) */
    KM_PROMPT,              /* op, once its argument is given (prompt says what kind) */
    KM_MENU,                /* the menu named by the legend: arg its index for km_menu, -1 not defined */
    KM_SHIFT,               /* arg 1 gold, 2 blue */
    KM_SOFT,                /* soft key arg (0..5) */
    KM_DEVICE,              /* arg: KM_DEV_* */
    KM_UNDEFINED            /* a legend with no meaning yet (reported, not guessed) */
} km_kind;

enum { KM_ARG_VAR = 1, KM_ARG_LABEL, KM_ARG_TARGET,     /* what a KM_PROMPT asks for */
       KM_ARG_DIGITS };                                 /* a digit setting, from the digit keys (app.h) */
enum { KM_DEV_OFF = 1, KM_DEV_UNDO };

typedef struct {
    km_kind kind;
    int op;                 /* an ab_op for KM_OP and KM_PROMPT */
    int arg;                /* the op's argument; the shift, soft key or device action */
    int prompt;             /* KM_ARG_* for KM_PROMPT */
    const char *legend;     /* as printed (UTF-8) */
} km_action;

enum { KM_FACE = 0, KM_GOLD = 1, KM_BLUE = 2 };

/* The action of key (row * 6 + column) in a shift; a key that does not exist is KM_NONE. */
const km_action *km_lookup(int key, int shift);

/* The menus, as data beside the legends (provisional until Michael rules the menus): a menu's six
   soft keys, each an action like a key's (an op, or an op that asks for its argument); KM_NONE for a
   soft key with nothing. Two are defined:
   - PRGM (abacus #3877): PRGM (the program-entry toggle, UG p.G-11), LBL, INPUT, SST, BST, CLPGM,
     the P4 panel's menu, so the panel, the app and the device agree;
   - DISP (Michael, #3901): FIX, SCI, ENG, each then a digit setting (UG p.1-21's "FIX_" prompt),
     ALL, and the complex display forms xiy and rθa (provisional picks).
   Until the menus are ruled, EQN (gold on 0) is the plain Equation-mode toggle (UG p.G-7), a
   provisional KM_OP the EQN menu's first item will take over. */
#define KM_SOFT_KEYS 6

typedef struct {
    const char *name;
    km_action item[KM_SOFT_KEYS];
} km_menu;

const km_menu *km_menu_at(int index);   /* NULL when there is no such menu */

/* The letter layer: what each key types while a KM_PROMPT waits for its argument (the P4 panel's
   assignment, abacus #3826, provisional until Michael rules where letters are printed; the 35s
   prints a letter on each key, UG p.1-3). The table is data in the generator, so a printed legend
   later changes only data. */
typedef enum { KL_NONE = 0, KL_LETTER, KL_IND_I, KL_IND_J, KL_ESC, KL_ARITH } kl_kind;

typedef struct {
    kl_kind kind;
    int value;              /* KL_LETTER: 0..25 for A..Z; KL_ARITH: AB_ADD, AB_SUB, AB_MUL, AB_DIV */
} km_letter;

const km_letter *km_letter_of(int key);

/* STO or RCL followed by + - x / is STO+ ... RCL/ (UG p.3-6, 3-7); -1 for any other pair. */
int km_arith_op(int op, int arith);

/* The argument a prompt of kind KM_ARG_* takes from a letter-layer key: a variable code (A..Z,
   (I), (J)), a label 0..25, or a target (a label's first line, or (I) / (J)); -1 when the key
   gives nothing that prompt takes (a label cannot be (I)). */
int km_prompt_arg(int prompt, const km_letter *l);

#endif
